using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.NTF.NotificacionesVisualizadas;using GraphApi.Services.NTF.NotificacionesVisualizadas;namespace GraphApi.Controllers.NTF.NotificacionesVisualizadas{    /// <summary>    /// Gestión de NotificacionesVisualizadas: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("NTF/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre NotificacionesVisualizadas")]    public class NotificacionesVisualizadasController : Controller    {        private readonly INotificacionesVisualizadasService _objService;        public NotificacionesVisualizadasController(INotificacionesVisualizadasService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los NotificacionesVisualizadas, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="notificacionVisualizadaID">NotificacionVisualizadaID</param>        /// <param name="notificacionID">NotificacionID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="fechaLectura">FechaLectura</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de NotificacionesVisualizadas</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar NotificacionesVisualizadas",            Description = "Devuelve NotificacionesVisualizadas aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadNotificacionesVisualizadas>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadNotificacionesVisualizadas>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? notificacionVisualizadaID,            [FromQuery] int? notificacionID,            [FromQuery] int? usuarioID,            [FromQuery] DateTime? fechaLectura,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetNotificacionesVisualizadasDynamic(                notificacionVisualizadaID,                 notificacionID,                 usuarioID,                 fechaLectura,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo NotificacionesVisualizada.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del NotificacionesVisualizada a crear.</param>        /// <returns>El NotificacionesVisualizada recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear NotificacionesVisualizadas",            Description = "Inserta un nuevo NotificacionesVisualizada en la base de datos."        )]        [ProducesResponseType(typeof(clReadNotificacionesVisualizadas), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadNotificacionesVisualizadas>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateNotificacionesVisualizadas objInput)        {            var vCreated = await _objService.CreateNotificacionesVisualizadas(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de NotificacionesVisualizada.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del NotificacionesVisualizada.</param>        /// <returns>El NotificacionesVisualizada actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar NotificacionesVisualizadas",            Description = "Actualiza uno o varios campos de NotificacionesVisualizada existente."        )]        [ProducesResponseType(typeof(clReadNotificacionesVisualizadas), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadNotificacionesVisualizadas>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateNotificacionesVisualizadas objInput)        {            var vUpdated = await _objService.UpdateNotificacionesVisualizadas(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un NotificacionesVisualizada por su ID.        /// </summary>        [HttpDelete("{nNotificacionesVisualizadasID:int}")]        [SwaggerOperation(            Summary = "Eliminar NotificacionesVisualizada",            Description = "Borra un NotificacionesVisualizada si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nNotificacionesVisualizadasID)        {            var success = await _objService.DeleteNotificacionesVisualizadas(nNotificacionesVisualizadasID);            return success ? NoContent() : NotFound();        }    }}